  "This request comes from the Bulk Builder (PLAN pass). Read the instruction and the design fields, then LIST the outputs you will produce, LABELS ONLY (no field content). Return ONLY a raw JSON object: {\"translate\": <true ONLY if the instruction asks to translate/localize into languages, else false>, \"labels\": [ ... ]}. When translate is true the labels are the LANGUAGE NAMES (written in the same language the user used). Otherwise the labels are a distinct short topic/seed per output. Honor any quantity named in the instruction; otherwise a sensible set (about 6 to 12). Hard cap 500.\n": "Cette requête provient du Bulk Builder (PLAN pass). Lisez les instructions et les champs de conception, puis LISTEZ les résultats que vous produirez, ÉTIQUETTES UNIQUEMENT (pas de contenu de champ). Renvoie UNIQUEMENT un objet JSON brut : {\"translate\": <true ONLY if the instruction asks to translate/localize into languages, else false>, \"labels\": [ ... ]}. Lorsque la traduction est vraie, les étiquettes sont les NOMS DE LANGUE (écrits dans la même langue que celle utilisée par l'utilisateur). Sinon, les étiquettes sont un court sujet/graine distinct par sortie. Honorez toute quantité nommée dans l’instruction ; sinon un ensemble raisonnable (environ 6 à 12). Casquette rigide 500.\n",
