  "Create your dika studio account": "Créez votre compte dika studio",
  "An account unlocks the online template and asset library, and release news. The editor itself works either way.": "Un compte donne accès aux modèles et à la bibliothèque de ressources en ligne ainsi qu’aux actualités. L’éditeur fonctionne avec ou sans compte.",
  "This app could not reach dika studio just now, so the full sign-up flow is not available.": "Cette application n’a pas pu joindre dika studio pour le moment ; l’inscription complète n’est donc pas disponible.",
  "You can carry on using the editor: everything except the online library works offline.": "Vous pouvez continuer à utiliser l'éditeur : tout sauf la bibliothèque en ligne fonctionne hors ligne.",
  "It will ask again next time you open it.": "Il vous demandera à nouveau la prochaine fois que vous l'ouvrirez.",
  "Registration wizard": "Assistant d'inscription",
  "<div style=\"font-size:28px;font-weight:700;color:var(--text);margin-bottom:4px\">dika studio</div>": "<div style=\"font-size:28px;font-weight:700;color:var(--text);margin-bottom:4px\">dika studio</div>",
  "<div style=\"font-size:13px;color:var(--text-dim);margin-bottom:20px\">Multi-Product Design Platform</div>": "<div style=\"font-size:13px;color:var(--text-dim);margin-bottom:20px\">Plateforme de design multi-produits</div>",
  "<div style=\"font-size:12px;color:var(--text-faint);margin-bottom:4px\">Version 2.0</div>": "<div style=\"font-size:12px;color:var(--text-faint);margin-bottom:4px\">Version 2.0</div>",
  "<div style=\"font-size:12px;color:var(--text-faint);margin-bottom:20px\">Built by <a href=\"https://mirexagency.com\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--gold);text-decoration:none\">Mirex Agency</a></div>": "<div style=\"font-size:12px;color:var(--text-faint);margin-bottom:20px\">Créé par <a href=\"https://mirexagency.com\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--gold);text-decoration:none\">Mirex Agency</a></div>",
  "<div style=\"font-size:11px;color:var(--text-faint);margin-bottom:22px\">&copy; 2026 Mirex Agency. Released under the Business Source License 1.1.</div>": "<div style=\"font-size:11px;color:var(--text-faint);margin-bottom:22px\">© 2026 Agence Mirex. Publié sous Business Source License 1.1.</div>",
  "<div style=\"font-size:11px;color:var(--text-faint);margin-top:10px\">Reset clears only the wizard's own record. Your projects, settings and keys are untouched.</div>": "<div style=\"font-size:11px;color:var(--text-faint);margin-top:10px\">Réinitialiser efface uniquement les données de l’assistant. Vos projets, réglages et clés restent inchangés.</div>",
  "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:16px\">Need help? Contact us:</p>": "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:16px\">Besoin d’aide ? Contactez-nous :</p>",
  "<div style=\"margin-bottom:12px\"><a href=\"https://mirexagency.com\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--gold);text-decoration:none;font-size:13px\">Visit our website</a></div>": "<div style=\"margin-bottom:12px\"><a href=\"https://mirexagency.com\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--gold);text-decoration:none;font-size:13px\">Visiter notre site</a></div>",
  "<div style=\"margin-bottom:12px\"><a href=\"mailto:support@dika.studio\" style=\"color:var(--gold);text-decoration:none;font-size:13px\">Email support@dika.studio</a></div>": "<div style=\"margin-bottom:12px\"><a href=\"mailto:support@dika.studio\" style=\"color:var(--gold);text-decoration:none;font-size:13px\">Envoyer un e-mail à support@dika.studio</a></div>",
  "settings: about": "paramètres : à propos",
