  "<div>Plan: ": "<div>Forfait : ",
  "<button type=\"button\" class=\"btn-xs\" id=\"account-manage\" style=\"padding:7px 14px;background:var(--surface3);border:1px solid var(--border);border-radius:4px;color:var(--text-dim);cursor:pointer;font-size:12px\">Manage account</button>": "<button type=\"button\" class=\"btn-xs\" id=\"account-manage\" style=\"padding:7px 14px;background:var(--surface3);border:1px solid var(--border);border-radius:4px;color:var(--text-dim);cursor:pointer;font-size:12px\">Gérer le compte</button>",
  "<button type=\"button\" class=\"btn-xs\" id=\"account-signout\" style=\"padding:7px 14px;background:transparent;border:1px solid var(--border);border-radius:4px;color:var(--text-dim);cursor:pointer;font-size:12px\">Sign out</button>": "<button type=\"button\" class=\"btn-xs\" id=\"account-signout\" style=\"padding:7px 14px;background:transparent;border:1px solid var(--border);border-radius:4px;color:var(--text-dim);cursor:pointer;font-size:12px\">Se déconnecter</button>",
  "<p style=\"font-size:11px;color:var(--text-faint);margin-top:8px;line-height:1.5\">": "<p style=\"font-size:11px;color:var(--text-faint);margin-top:8px;line-height:1.5\">",
