  "settings: sleep": "paramètres : sommeil",
  "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:12px\">Auto-save times from this browser. The latest state is stored under <span style=\"color:var(--text-faint);font-size:12px\">dika_autosave</span>; rolling snapshots use <span style=\"color:var(--text-faint);font-size:12px\">dika_versions</span>.</p>": "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:12px\">Enregistrement automatique des heures à partir de ce navigateur. Le dernier état est stocké sous <span style=\"color:var(--text-faint);font-size:12px\">dika_autosave</span> ; les instantanés glissants utilisent <span style=\"color:var(--text-faint);font-size:12px\">dika_versions</span>.</p>",
  "<div style=\"font-size:14px;color:var(--text)\">": "<div style=\"font-size:14px;color:var(--text)\">",
  "<p style=\"color:var(--text-dim);font-size:13px;margin:0\">No <code>dika_autosave</code> entry yet.</p>": "<p style=\"color:var(--text-dim);font-size:13px;margin:0\">Aucune entrée <code>dika_autosave</code> pour le moment.</p>",
  "<ul id=\"settings-vh-list\" style=\"margin:0 0 12px 0;padding:0 0 0 18px;color:var(--text-dim);font-size:12px;max-height:240px;overflow-y:auto;line-height:1.4\">": "<ul id=\"settings-vh-list\" style=\"margin:0 0 12px 0;padding:0 0 0 18px;color:var(--text-dim);font-size:12px;max-height:240px;overflow-y:auto;line-height:1.4\">",
  " — <span style=\"color:var(--text-faint)\">": " — <span style=\"color:var(--text-faint)\">",
  "<p style=\"color:var(--text-faint);font-size:12px;margin-bottom:12px\">No rolling snapshots yet (they are added on each auto-save tick).</p>": "<p style=\"color:var(--text-faint);font-size:12px;margin-bottom:12px\">Aucun instantané glissant pour le moment (ils sont ajoutés à chaque sauvegarde automatique).</p>",
  "<span style=\"font-size:10px;color:var(--text-faint);margin-top:6px;display:block\">Clears stored version snapshots (<code>dika_versions</code>). Current canvas and latest auto-save file are not removed.</span>": "<span style=\"font-size:10px;color:var(--text-faint);margin-top:6px;display:block\">Efface les instantanés de versions enregistrés (<code>dika_versions</code>). Le canevas actuel et le dernier fichier de sauvegarde automatique ne sont pas supprimés.</span>",
