  "Stil": "Style",
  "Add products from the panel's Assets > Products section, and they'll appear here automatically.": "Ajoutez des produits à partir de la section Actifs > Produits du panneau et ils apparaîtront ici automatiquement.",
  "A design and video studio that runs on this machine.": "Un studio de design et de vidéo qui tourne sur cette machine.",
  "Your work stays here. Documents, media and version history never leave this computer.": "Votre travail reste ici. Les documents, les médias et l'historique des versions ne quittent jamais cet ordinateur.",
  "Free to use. Source available under the Business Source License 1.1.": "Utilisation gratuite. Code source disponible sous la Business Source License 1.1.",
  "Your projects are stored in this browser profile. That is the only copy.": "Vos projets sont stockés dans ce profil de navigateur. C'est la seule copie.",
  "Clearing site data deletes them. So does a different browser, or a fresh profile.": "La suppression des données du site les supprime. Il en va de même pour un autre navigateur ou un nouveau profil.",
  "Export a project file for anything you want to keep. It carries the design and its media, and it opens on any machine.": "Exportez un fichier de projet pour tout ce que vous souhaitez conserver. Il porte le design et ses supports, et s'ouvre sur n'importe quelle machine.",
  "Export a project file now": "Exporter un fichier de projet maintenant",
  "Remind me to export": "Rappelle-moi d'exporter",
  "Never": "Jamais",
  "Weekly": "Hebdomadaire",
  "Monthly": "Mensuel",
  "That is everything. Your work stays on this machine.": "C'est tout. Votre travail reste sur cette machine.",
  "You can reopen this from Settings > About.": "Vous pouvez le rouvrir depuis Paramètres > À propos.",
  "Start using it": "Commencez à l'utiliser",
  "Your profile data is used in contact presets and bulk export.": "Vos données de profil sont utilisées dans les préréglages de contact et l’exportation groupée.",
  "JOB TITLE": "TITRE D'EMPLOI",
  "ADDRESS": "ADRESSE",
  "Social Media": "Réseaux sociaux",
  "Save Profile": "Enregistrer le profil",
  "An account unlocks the online template and asset library, and release news. The editor itself works either way, online or offline.": "Un compte donne accès aux modèles et à la bibliothèque de ressources en ligne ainsi qu’aux actualités. L’éditeur fonctionne en ligne comme hors ligne.",
  "Sign in to unlock:": "Connectez-vous pour débloquer :",
  "The online template and asset library": "La bibliothèque de modèles et d'actifs en ligne",
  "Release news and early access to new features": "Publication d'actualités et accès anticipé aux nouvelles fonctionnalités",
  "The editor itself works either way, with or without an account, online or offline.": "L'éditeur lui-même fonctionne dans les deux sens, avec ou sans compte, en ligne ou hors ligne.",
  "Create an account": "Créer un compte",
  "WHAT THIS APP SENDS": "CE QUE CETTE APPLICATION ENVOIE",
  "Once a day: an install id, the app version, your platform and language, and your account id once you sign in.": "Une fois par jour : un identifiant d'installation, la version de l'application, votre plateforme et votre langue, ainsi que votre identifiant de compte une fois connecté.",
  "Nothing about your designs. No document, no title, no file name, no image.": "Aucune information sur vos designs : aucun document, titre, nom de fichier ou image.",
  "WHERE THE SESSION IS KEPT": "OÙ LA SÉANCE EST CONSERVÉE",
  "You are running the browser build, where every local page shares one storage area, so another local file opened in this browser could read this session. It is therefore short-lived (about 24 hours) and can only read the template library. The desktop app keeps its own isolated storage.": "Vous exécutez la version du navigateur, où chaque page locale partage une zone de stockage, afin qu'un autre fichier local ouvert dans ce navigateur puisse lire cette session. Il est donc de courte durée (environ 24 heures) et ne peut lire que la bibliothèque de modèles. L'application de bureau conserve son propre stockage isolé.",
  "Your own keys for the stock media providers. They fill the Images and Audio search tabs, and the GIFs and Stickers tabs in Items. Every provider below has a free tier.": "Vos clés pour les fournisseurs de médias libres de droits. Elles alimentent les onglets de recherche Images et Audio, ainsi que les onglets GIF et Autocollants dans Éléments. Chaque fournisseur ci-dessous propose une offre gratuite.",
  "These keys are stored in this browser only, and this build never sends them anywhere except to the provider itself. Anyone with access to this computer or its browser profile can read them, so use a restricted key with the lowest quota you need.": "Ces clés sont stockées uniquement dans ce navigateur et cette version ne les envoie jamais ailleurs qu'au fournisseur lui-même. Toute personne ayant accès à cet ordinateur ou à son profil de navigateur peut les lire, utilisez donc une clé restreinte avec le quota le plus bas dont vous avez besoin.",
  "Save keys": "Enregistrer les clés",
  "1. Go to unsplash.com/oauth/applications and create an app": "1. Accédez à unsplash.com/oauth/applications et créez une application",
  "2. Copy the Access Key, not the Secret Key": "2. Copiez la clé d'accès, pas la clé secrète",
  "Header: Authorization: Client-ID YOUR_KEY - 50 req/hr on demo, 5000 req/hr in production": "En-tête : Autorisation : ID client YOUR_KEY - 50 req/h en démo, 5 000 req/h en production",
  "1. Go to pexels.com/api and request a key": "1. Accédez à pexels.com/api et demandez une clé",
  "2. It is issued instantly": "2. Il est délivré instantanément",
  "Header: Authorization: YOUR_KEY - 200 req/hr, 20K req/month": "En-tête : Autorisation : YOUR_KEY - 200 req/h, 20 000 req/mois",
  "1. Go to pixabay.com/api/docs/ and sign up": "1. Allez sur pixabay.com/api/docs/ et inscrivez-vous",
  "2. Copy the key shown on the docs page": "2. Copiez la clé affichée sur la page de documentation",
  "500K+ CC-licensed sound effects - header: Authorization: Token YOUR_KEY": "Plus de 500 000 effets sonores sous licence CC - en-tête : Autorisation : Jeton YOUR_KEY",
  "1. Go to freesound.org/apiv2/apply and create an API app": "1. Accédez à freesound.org/apiv2/apply et créez une application API",
  "2. Copy the API Token": "2. Copiez le jeton API",
  "1. Go to devportal.jamendo.com and register an app": "1. Accédez à devportal.jamendo.com et enregistrez une application",
  "2. Copy the Client ID": "2. Copiez l'ID client",
  "1. Go to developers.giphy.com and create an app": "1. Accédez à Developers.giphy.com et créez une application",
  "2. Copy the API Key": "2. Copiez la clé API",
