  "Auto-save times from this browser. The latest state is stored under dika_autosave; rolling snapshots use dika_versions.": "Sauvegarde automatique des heures à partir de ce navigateur. Le dernier état est stocké sous dika_autosave ; les instantanés glissants utilisent dika_versions.",
  "Clear History": "Effacer l'historique",
  "Customize shortcuts, manage profiles, and resolve conflicts across all app modules.": "Personnalisez les raccourcis, gérez les profils et résolvez les conflits entre tous les modules de l’application.",
