  "Skip Startup Wizard": "Ignorer l'assistant de démarrage",
  "In multi-page projects, to keep the app fast, pages you haven't opened for a long time are put to sleep in the background. Their content is safely stored and instantly returns when you click its tab. The page you're working on, a few nearby pages, and video / infinite canvas / slide / board pages always stay open.": "Dans les projets multipages, les pages que vous n’avez pas ouvertes depuis longtemps sont mises en veille en arrière-plan pour garder l’application rapide. Leur contenu est conservé en toute sécurité et revient instantanément lorsque vous cliquez sur leur onglet. La page active, quelques pages voisines et les pages vidéo, canevas infini, diapositive et tableau restent toujours ouvertes.",
  "Automatic sleep": "Sommeil automatique",
  "Maximum awake pages (pages older than this number sleep)": "Nombre maximal de pages actives (les pages plus anciennes que ce nombre sont mises en veille)",
  "Neighbor window (pages kept awake on each side of the active page)": "Fenêtre de voisinage (pages maintenues actives de chaque côté de la page actuelle)",
