  "Export a project file first if you want to keep anything. This does not uninstall the program itself: use Windows Settings for that.": "Exportez d’abord un fichier de projet si vous souhaitez conserver quelque chose. Cela ne désinstalle pas le programme lui-même : utilisez les paramètres Windows pour cela.",
